// ManagedHTTPS is the HTTPS helper part of the web setup/edit form. The public
// endpoint is still TunnelPort/ServerAddr; InternalPort stays on loopback.
// Empty server identities are generated by the same helpers as the CLI. An
// empty password/private key on edit keeps the existing secret.
type ManagedHTTPS struct {
	InternalPort string `json:"internalPort"`
	Binary       string `json:"binary"`
	Username     string `json:"username"`
	Password     string `json:"password,omitempty"`
	ServerName   string `json:"serverName"`
	Certificate  string `json:"certificate"`
	Key          string `json:"key"`
	CAFile       string `json:"caFile"`
	// CAPEM carries public trust from a peer link to a managed node. It is not
	// returned in settings; the destination validates it and stores it locally.
	CAPEM      string `json:"caPem,omitempty"`
	UUID       string `json:"uuid"`
	Path       string `json:"path"`
	Host       string `json:"host"`
	Target     string `json:"target"`
	PrivateKey string `json:"privateKey,omitempty"`
	PublicKey  string `json:"publicKey"`
	ShortID    string `json:"shortId"`
	sent       map[string]bool
}

func (m *ManagedHTTPS) UnmarshalJSON(raw []byte) error {
	type plain ManagedHTTPS
	var value plain
	decoder := json.NewDecoder(strings.NewReader(string(raw)))
	decoder.DisallowUnknownFields()
	if err := decoder.Decode(&value); err != nil {
		return err
	}
	var keys map[string]json.RawMessage
	if err := json.Unmarshal(raw, &keys); err != nil {
		return err
	}
	*m = ManagedHTTPS(value)
	m.sent = map[string]bool{}
	for key := range keys {
		m.sent[key] = true
	}
	return nil
}

func (m ManagedHTTPS) MarshalJSON() ([]byte, error) {
	type plain ManagedHTTPS
	raw, err := json.Marshal(plain(m))
	if err != nil || m.sent == nil {
		return raw, err
	}
	var keys map[string]json.RawMessage
	if err := json.Unmarshal(raw, &keys); err != nil {
		return nil, err
	}
	for key := range keys {
		if !m.sent[key] {
			delete(keys, key)
		}
	}
	return json.Marshal(keys)
}

// Keep omitted edit fields distinct from explicitly cleared optional settings.
func (m ManagedHTTPS) merged(old ManagedHTTPS) ManagedHTTPS {
	v, out, typ := reflect.ValueOf(m), reflect.ValueOf(&old).Elem(), reflect.TypeOf(m)
	for i := 0; i < typ.NumField(); i++ {
		key := strings.Split(typ.Field(i).Tag.Get("json"), ",")[0]
		if key == "" || m.sent != nil && !m.sent[key] {
			continue
		}
		value := v.Field(i).String()
		if (key == "password" || key == "privateKey") && value == "" {
			continue
		}
		out.Field(i).SetString(value)
	}
	old.sent = nil
	return old
}

func managedHTTPSOf(s TunnelSpec) ManagedHTTPS {
	m := ManagedHTTPS{InternalPort: addrPort(s.BindAddr)}
	if s.Role == "client" {
		m.InternalPort = addrPort(s.RemoteAddr)
		if s.NaiveClient.Enabled() {
			x := s.NaiveClient
			m.Binary, m.Username, m.Password, m.CAFile = x.Binary, x.Username, x.Password, x.CAFile
		} else {
			x := s.XrayClient
			m.Binary, m.UUID, m.ServerName, m.Path, m.Host = x.Binary, x.UUID, x.ServerName, x.Path, x.Host
			m.CAFile, m.PublicKey, m.ShortID = x.CAFile, x.PublicKey, x.ShortID
		}
	} else if s.NaiveServer.Enabled() {
		x := s.NaiveServer
		m.Binary, m.Username, m.Password, m.Certificate, m.Key = x.Binary, x.Username, x.Password, x.Certificate, x.Key
		m.ServerName = managedCertificateHost(x.Certificate)
	} else {
		x := s.XrayServer
		m.Binary, m.UUID, m.ServerName, m.Path, m.Host = x.Binary, x.UUID, x.ServerName, x.Path, x.Host
		m.Certificate, m.Key, m.Target, m.PrivateKey, m.ShortID = x.Certificate, x.Key, x.Target, x.PrivateKey, x.ShortID
		if x.PrivateKey != "" {
			_, m.PublicKey, _ = managedRealityKey(x.PrivateKey)
		}
	}
	return m
}

// Naive verifies the address it dials; unlike Xray it has no separate SNI
// field. Recover that address from the server certificate for settings/links.
func managedCertificateHost(path string) string {
	raw, err := os.ReadFile(path)
	if err != nil {
		return ""
	}
	certs, err := managedLinkCertificates(string(raw))
	if err != nil || len(certs) == 0 {
		return ""
	}
	for _, host := range certs[0].DNSNames {
		if !strings.Contains(host, "*") {
			return host
		}
	}
	if len(certs[0].IPAddresses) != 0 {
		return certs[0].IPAddresses[0].String()
	}
	return ""
}

var webRealityProbe realitySetupProbe = probeRealitySetup

// The panel and CLI produce the same role-specific helper configuration and
// run the same validators. No helper is downloaded and TLS verification stays on.
func applyManagedHTTPS(s *TunnelSpec, transport, public string, m ManagedHTTPS) error {
	if m.CAPEM != "" {
		if s.Role != "client" || transport == "reality" || m.CAFile != "" {
			return fmt.Errorf("embedded CA trust belongs to a Naive/XHTTP client without an explicit CA file")
		}
		if _, err := managedLinkCertificates(m.CAPEM); err != nil {
			return err
		}
		m.CAFile = managedLinkCAPath(m.CAPEM)
	}
	internal := defaultString(strings.TrimSpace(m.InternalPort), "3080")
	if !validPort(internal) || internal == addrPort(public) {
		return fmt.Errorf("the internal reverse port must be valid and differ from the public HTTPS port")
	}
	if s.AcceptUDP || s.SimpleAuth || len(s.FallbackTransports) != 0 || s.Proxy != "" || s.LocalAddr != "" || s.Interface != "" || s.SOMark != 0 || len(s.FallbackAddrs) != 0 || s.HealthFailover || s.LoadBalance || s.EdgeIP != "" {
		return fmt.Errorf("managed HTTPS forwards TCP only and cannot use UDP, simple auth, proxy, route bindings or failover")
	}
	s.Transport = "tcp"
	clearManagedTransport(s)
	if s.Role == "server" {
		s.BindAddr = net.JoinHostPort("127.0.0.1", internal)
	} else {
		s.RemoteAddr = net.JoinHostPort("127.0.0.1", internal)
	}
	m.ServerName = strings.TrimSpace(m.ServerName)
	if transport == "naive" {
		m.Username = defaultString(m.Username, "backpack")
		if s.Role == "server" {
			m.Binary = defaultString(m.Binary, managedHelperPath("sing-box"))
			m.Password = defaultString(m.Password, randomToken(32))
		} else {
			m.Binary = defaultString(m.Binary, managedHelperPath("naive"))
		}
	} else {
		m.Binary = defaultString(m.Binary, managedHelperPath("xray"))
		if s.Role == "server" && m.UUID == "" {
			var err error
			m.UUID, err = managedUUID()
			if err != nil {
				return err
			}
		}
		if transport == "xhttp" && s.Role == "server" && m.Path == "" {
			m.Path = "/" + randomToken(24)
		}
	}
	if s.Role == "server" && transport == "reality" {
		var err error
		m.PrivateKey, _, err = managedRealityKey(m.PrivateKey)
		if err != nil {
			return err
		}
		if m.ShortID == "" {
			var raw [8]byte
			if _, err := rand.Read(raw[:]); err != nil {
				return err
			}
			m.ShortID = hex.EncodeToString(raw[:])
		}
	}
	if s.Role == "server" && transport != "reality" {
		if (m.Certificate == "") != (m.Key == "") {
			return fmt.Errorf("provide both the HTTPS certificate and its private key, or leave both empty")
		}
		if m.Certificate == "" {
			if m.ServerName == "" {
				return fmt.Errorf("a certificate hostname or IP is required to generate a private HTTPS certificate")
			}
			var err error
			m.Certificate, m.Key, err = EnsureSelfSignedCert(s.Name+"-https", m.ServerName)
			if err != nil {
				return err
			}
		}
	}
	if transport == "naive" && s.Role == "server" {
		s.NaiveServer = config.NaiveServerConfig{Binary: m.Binary, Listen: public, Username: m.Username, Password: m.Password, Certificate: m.Certificate, Key: m.Key}
	} else if transport == "naive" {
		s.NaiveClient = config.NaiveClientConfig{Binary: m.Binary, Server: public, Username: m.Username, Password: m.Password, CAFile: m.CAFile}
	} else if s.Role == "server" {
		s.XrayServer = config.XrayServerConfig{Binary: m.Binary, Listen: public, Mode: transport, UUID: m.UUID, ServerName: m.ServerName, Path: m.Path, Host: m.Host, Certificate: m.Certificate, Key: m.Key, Target: m.Target, PrivateKey: m.PrivateKey, ShortID: m.ShortID}
	} else {
		s.XrayClient = config.XrayClientConfig{Binary: m.Binary, Server: public, Mode: transport, UUID: m.UUID, ServerName: m.ServerName, Path: m.Path, Host: m.Host, CAFile: m.CAFile, PublicKey: m.PublicKey, ShortID: m.ShortID}
	}
	if m.CAPEM != "" {
		withoutCA := *s
		withoutCA.NaiveClient.CAFile, withoutCA.XrayClient.CAFile = "", ""
		if err := validateManagedSpec(withoutCA); err != nil {
			return err
		}
		if err := app.WriteFileAtomic(m.CAFile, []byte(m.CAPEM), 0600); err != nil {
			return err
		}
	}
	if err := validateManagedSpec(*s); err != nil {
		return fmt.Errorf("HTTPS configuration: %w", err)
	}
	if s.NaiveServer.Enabled() && m.ServerName != "" {
		if err := validateNaiveLinkHost(s.NaiveServer.Certificate, m.ServerName); err != nil {
			return err
		}
	}
	if s.Role == "server" && transport == "reality" {
		ctx, cancel := context.WithTimeout(context.Background(), 20*time.Second)
		defer cancel()
		if err := webRealityProbe(ctx, m.Target, m.ServerName, m.Binary); err != nil {
			return fmt.Errorf("REALITY cover check failed: %w", err)
		}
	}
	if why := managedEndpointClash(*s); why != "" {
		return fmt.Errorf("%s", why)
	}
	return nil
}

// Naive has no separate SNI override: its dial address must match the leaf
// certificate, even when the peer trusts that certificate explicitly.
func validateNaiveLinkHost(path, host string) error {
	raw, err := os.ReadFile(path)
	if err != nil {
		return err
	}
	certs, err := managedLinkCertificates(string(raw))
	if err != nil {
		return err
	}
	if err := certs[0].VerifyHostname(host); err != nil {
		return fmt.Errorf("the Naive dial hostname/IP %q does not match the HTTPS certificate: %w", host, err)
	}
	return nil
}

// Edit the public helper endpoint rather than the private engine listener.
// Credentials not resubmitted by the browser keep their current values.
func editedReverseSpec(original TunnelSpec, e TunnelEdit) (TunnelSpec, bool, error) {
	if isPeerSpec(original) || e.WatICMP != nil || e.Auto != nil {
		return editedPeerSpec(original, e)
	}
	s := original
	oldTransport := selectedTransport(s)
	target := defaultString(strings.ToLower(strings.TrimSpace(e.Transport)), oldTransport)
	var managed ManagedHTTPS
	if managedTransport(oldTransport) {
		managed = managedHTTPSOf(s)
		public := managedEndpoint(s)
		if s.Role == "server" {
			s.BindAddr = public
		} else {
			s.RemoteAddr = public
		}
		clearManagedTransport(&s)
	}
	if managedTransport(target) {
		if !presetSuitsTransport(s.Preset, "tcp") {
			// Preserve local tuning, but an inherited KCP-only label cannot
			// describe a TCP helper. Explicitly posting it is still refused.
			s.Preset = ""
		}
		if oldTransport != target {
			managed = ManagedHTTPS{}
			// Switching follows the CLI: retire the old carrier's connectivity.
			s.AcceptUDP, s.SimpleAuth, s.HealthFailover, s.LoadBalance = false, false, false, false
			s.FallbackAddrs, s.FallbackTransports = nil, nil
			s.FallbackDwell, s.SOMark = 0, 0
			s.Proxy, s.LocalAddr, s.Interface, s.EdgeIP = "", "", "", ""
			s.ACMEDomain, s.ACMEEmail = "", ""
		}
		if e.Managed != nil {
			managed = e.Managed.merged(managed)
		}
		e.Transport = "tcp"
	} else if e.Managed != nil {
		return s, false, fmt.Errorf("HTTPS settings require naive, xhttp or reality")
	}
	shown := tuneOf(original)
	for _, step := range []func(*TunnelSpec) (bool, error){e.editTransport, func(s *TunnelSpec) (bool, error) { return e.editTuning(s, shown) }, e.editCertificate, e.editTunnelPort, e.editServerAddr, e.editPorts, e.editAdvanced, e.editProxyProtocol} {
		if _, err := step(&s); err != nil {
			return s, false, err
		}
	}
	if managedTransport(target) {
		public := s.BindAddr
		if s.Role == "client" {
			public = s.RemoteAddr
		}
		if err := applyManagedHTTPS(&s, target, public, managed); err != nil {
			return s, false, err
		}
	}
	return s, !reflect.DeepEqual(original, s), nil
}
